            if 0 <= y < len(grid) and 0 <= x < len(grid[y]):
                return grid[y][x]
        except Exception:
            return None
        return None

    best_move = (0, 0)
    best_score = None

    for dx, dy in candidates:
        nx, ny = me[0] + dx, me[1] + dy
