                if (tx, ty) not in blocked:
                    if width is None or height is None or (0 <= tx < width and 0 <= ty < height):
                        open_count += 1
        score += open_count * 2

        # Mild center bias if map size known
        if width is not None and height is not None:
            cx, cy = (width - 1) / 2.0, (height - 1) / 2.0
            score -= int(abs(nx - cx) + abs(ny - cy))

        cv = cell_value(nx, ny)
        if isinstance(cv, (int, float)):
            score += 1 if cv == 0 else 0
        elif isinstance(cv, str):
            low = cv.lower()
            if any(t in low for t in ("wall", "block", "obstacle")):
