            if any(t in low for t in ("enemy", "opponent", "hazard", "predator")):
                score -= 20

        # Slight preference for movement over staying still when useful
        if dx == 0 and dy == 0:
            score -= 1

        if best_score is None or score > best_score:
            best_score = score
            best_move = (dx, dy)

    return [best_move[0], best_move[1]]

